const body = $input.first().json.body ?? $input.first().json;

const expectedSecret = $env.WEBHOOK_SECRET || '';
const allowedSymbols = ['US100', 'NAS100', 'USTEC', 'NASDAQ:NDX', 'USATECHIDXUSD'];
const tpPoints = Number($env.TP_POINTS || 50);
const slPoints = Number($env.SL_POINTS || 25);

const errors = [];

if (!body || typeof body !== 'object') {
  errors.push('Kein gueltiger JSON-Body empfangen.');
}

if (expectedSecret && body.secret !== expectedSecret) {
  errors.push('Ungueltiges oder fehlendes Secret.');
}

const symbol = (body.symbol || '').toString().toUpperCase();
if (!allowedSymbols.includes(symbol)) {
  errors.push(`Symbol '${symbol}' ist nicht freigegeben (erlaubt: ${allowedSymbols.join(', ')}).`);
}

const action = (body.action || '').toString().toLowerCase();
if (!['buy', 'sell', 'long', 'short'].includes(action)) {
  errors.push(`Unbekannte Order-Richtung '${action}'.`);
}

const price = Number(body.price);
if (!Number.isFinite(price)) errors.push('price fehlt oder ist keine Zahl.');

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      errors,
      rawBody: body
    }
  }];
}

const isLong = ['buy', 'long'].includes(action);
const directionLabel = isLong ? 'LONG' : 'SHORT';
const emoji = isLong ? '🟢' : '🔴';

// TP/SL werden hier berechnet, da TradingView-Alert-Nachrichten keine Arithmetik unterstuetzen.
const tp = isLong ? price + tpPoints : price - tpPoints;
const sl = isLong ? price - slPoints : price + slPoints;
const riskRewardRatio = slPoints > 0 ? (tpPoints / slPoints).toFixed(2) : 'n/a';

const message = [
  `${emoji} *US100 ${directionLabel} Signal*`,
  '',
  `Symbol: \`${symbol}\``,
  `Entry: \`${price}\``,
  `TP: \`${tp}\` (+${tpPoints} Punkte)`,
  `SL: \`${sl}\` (-${slPoints} Punkte)`,
  `CRV: \`${riskRewardRatio}\``,
  '',
  `Zeit: ${body.time || new Date().toISOString()}`
].join('\n');

return [{
  json: {
    valid: true,
    symbol,
    action: directionLabel,
    price,
    tp,
    sl,
    riskRewardRatio,
    message
  }
}];
